<script setup lang="ts">
import type {PayrollComparison} from '../payrollProgressTypes'
import {signedPayrollDelta,usePayrollProgressText} from '../payrollProgressText'
defineProps<{comparison:PayrollComparison;title:string}>()
const g=usePayrollProgressText(),money=signedPayrollDelta
